referenceSolutions.javascript:
function undoDrawerFirstQualifyingSlip(readings, k) {
  const a=readings; let out=[];
  for(const x of a){if(x>=0)out.push(x);else for(let i=0;i<-x&&out.length;i++)out.pop();}
  return out.find(x=>x>=k)??-1;
}

